setUnit('cbse-11-mathematics-ch09');
await import('./questions.mjs');
await import('./questions2.mjs');
const DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const P = (x, y) => pt(x, y);
const dec2 = (v) => (Math.round(v * 100) / 100).toString();

/**
 * A coordinate figure. lines: [L, [x0, x1]?, label?] drawn as functions on their domains; vl: [L, label] vertical lines;
 * segs: [label, [p, q]] helper segments; pts: [name, p, free?]. A point must lie on a drawn line unless it is free.
 */
function fig({ x, y, lines = [], vl = [], segs = [], pts = [] }, alt, caption) {
  const fns = lines.map(([L, dom, label]) => {
    must(slopeOf(L) !== null, 'function lines are not vertical');
    const dm = dom ?? x;
    must(dm[0] >= x[0] && dm[1] <= x[1] && dm[0] < dm[1], `domain inside the view for ${eqTex(L)}`);
    return { expr: expr(L), label: label ?? `$${yTex(L)}$`, domain: dm, L };
  });
  const out = pts.map(([name, p, free]) => {
    const onFn = fns.some((f) => on(f.L, p) && p[0].num() >= f.domain[0] - 1e-9 && p[0].num() <= f.domain[1] + 1e-9);
    const onV = vl.some(([L]) => on(L, p));
    must(free || onFn || onV, `figure point ${name} lies on a drawn line`);
    if (!free && p[1].isZero()) for (const f of fns) if (on(f.L, p)) must(f.domain[0] < p[0].num(), `marked zero ${name} not at the left end`);
    return [p[0].num(), p[1].num(), lab(name, p), onFn ? undefined : 'free'];
  });
  const v = plot({ x, y, fns: fns.map(({ expr: e, label, domain }) => ({ expr: e, label, domain })), pts: out, series: segs.map(([label, ps]) => ({ label, points: ps.map((p) => [p[0].num(), p[1].num()]), kind: 'line' })) }, alt, caption);
  v.spec.points.forEach((p, i) => { if (out[i][3] === 'free') p.on_curve = false; });
  if (vl.length) v.spec.vlines = vl.map(([L, label]) => ({ x: xInt(L).num(), label: label ?? `$${yTex(L)}$`, dashed: true }));
  return v;
}
const same = (L, a, b, c) => L.a === a && L.b === b && L.c === c;

// ================================================================ deck 1 visuals
const M0 = P(2, -1), Lr = through(M0, 1), Lf = through(M0, -2), Lh = through(M0, 0), Lv = through(M0, null);
