const incl = [['0', '0', 'horizontal'], ['30', r`\dfrac{1}{\sqrt{3}}`, 'rising gently'], ['45', '1', 'rising at equal steps'], ['60', r`\sqrt{3}`, 'rising steeply'], ['90', null, 'vertical'], ['120', r`-\sqrt{3}`, 'falling steeply'], ['135', '-1', 'falling at equal steps']];
