const tIncl = table(['Inclination $\\theta$', 'Slope $m = \\tan\\theta$', 'The line is'], incl.map(([t, m, s]) => [`$${t}^\\circ$`, m === null ? 'not defined' : `$${m}$`, s]), 'Table of inclinations and slopes: 0 degrees gives slope 0; 30 degrees gives one over root three; 45 degrees gives 1; 60 degrees gives root three; a vertical line at 90 degrees has no slope; 120 degrees gives minus root three; 135 degrees gives minus 1.', 'The slope is the tangent of the inclination.');

