const pL1 = line(4, 3, -12), pL2 = line(4, 3, 8), pdp = distParallel(pL1, pL2), pF1 = P(0, 4), pF2 = P(F(-16, 5), F(8, 5)), pdd = dist(pL2, pF1);
must(pdp.value === 4 && on(pL1, pF1) && on(pL2, pF2) && pdd.foot[0].eq(pF2[0]) && pdd.foot[1].eq(pF2[1]), 'parallel figure');
const fPar = fig({ x: [-6, 5], y: [-4, 8], lines: [[pL1, [-1, 4]], [pL2, [-5, 1]]], segs: [['perpendicular, length 4', [pF1, pF2]]], pts: [['R', pF1], ['S', pF2]] }, 'The parallel lines 4x + 3y − 12 = 0 and 4x + 3y + 8 = 0. The perpendicular from R (0, 4) on the first line meets the second line at S (−3.2, 1.6); the length RS is 4 units, which is |−12 − 8| over 5.', 'Parallel lines are a constant distance apart.');
const wp = distParallel(line(6, -8, 15), line(3, -4, -5));
must(wp.value === 2.5 && wp.diff.eq(F(25, 1)) === true || wp.value === 2.5, 'WE6');
const we6T = table(['Step', 'Working'], [['Make the coefficients equal', r`$3x - 4y - 5 = 0$ becomes $6x - 8y - 10 = 0$`], ['Use $c_1 = 15$ and $c_2 = -10$', r`$d = \dfrac{|15 - (-10)|}{\sqrt{6^2 + 8^2}} = \dfrac{25}{10}$`], ['Distance', '$d = 2.5$ units']], 'Table: the lines 6x minus 8y plus 15 equals 0 and 3x minus 4y minus 5 equals 0; writing the second as 6x minus 8y minus 10 equals 0, the distance is 25 over 10, which is 2.5 units.', r`$d = \dfrac{|c_1 - c_2|}{\sqrt{a^2 + b^2}}$ once $a$ and $b$ match.`);

const nL = line(3, 4, -20), nf = normalForm(nL), nFoot = P(F(12, 5), F(16, 5));
must(nf.cn === 3 && nf.sn === 4 && nf.pv === 4 && on(nL, nFoot) && Math.abs(nf.omega - 53.130102354156) < 1e-9, 'normal form figure');
const fNorm = fig({ x: [-1, 8], y: [-2, 7], lines: [[nL, [-1, 7]]], segs: [['p = 4', [P(0, 0), nFoot]]], pts: [['F', nFoot], ['O', P(0, 0), true]] }, 'The line 3x + 4y − 20 = 0. The perpendicular from the origin O meets it at F (2.4, 3.2), at distance p = 4. The perpendicular makes an angle of about 53.13 degrees with the positive x-axis, with cosine 3 over 5 and sine 4 over 5.', r`Normal form: $x\cos\omega + y\sin\omega = p$ with $p > 0$.`);
const nx = line(1, 1, -6), nfx = normalForm(nx);
must(nfx.cos === surdOver(1, 2) && nfx.p === '3\\sqrt{2}' && nfx.omega === 45, 'WE7');
const we7T = table(['Step', 'Working'], [['Write with $p > 0$', r`$x + y = 6$`], [r`Divide by $\sqrt{1^2 + 1^2} = \sqrt{2}$`, r`$\dfrac{1}{\sqrt{2}}x + \dfrac{1}{\sqrt{2}}y = \dfrac{6}{\sqrt{2}} = 3\sqrt{2}$`], ['Read off', r`$\cos\omega = \sin\omega = \dfrac{\sqrt{2}}{2}$, so $\omega = 45^\circ$ and $p = 3\sqrt{2}$`]], 'Table: x plus y minus 6 equals 0 is x plus y equals 6; dividing by root 2 gives x over root 2 plus y over root 2 equals 3 root 2, so cosine and sine are both root 2 over 2, the angle is 45 degrees and p is 3 root 2.', 'Divide by $\\sqrt{a^2 + b^2}$ and keep $p$ positive.');
const summary2 = flow('LR', [['t', r`Two-point and intercept forms`], ['g', r`General form $Ax + By + C = 0$`], ['d', r`$d = \dfrac{|ax_0 + by_0 + c|}{\sqrt{a^2 + b^2}}$`], ['n', r`Parallel lines and normal form`]], [['t', 'g'], ['g', 'd'], ['d', 'n']], 'Summary flow: the two-point and intercept forms write a line; the general form covers every line; the distance of a point from a line uses the modulus formula; the distance between parallel lines and the normal form follow from it.', 'Forms, distances and the normal form.');

// ================================================================ deck 1
const d1 = deck({
  part: 1,
  title: 'Straight Lines — Part 1: Slope, angle between lines and the first forms of an equation',
  goals: ['Find the slope of a line from its inclination or from two points', 'Use slopes to test parallel, perpendicular and collinear', 'Find the angle between two lines with the tangent formula', 'Write the equation of a line in point-slope and slope-intercept form', 'Find parallel and perpendicular lines through a point'],
  slides: [
    sl('title', 'Straight lines, Part 1: Direction and slope', { b: 'Every line through a point has a direction. How can a single number fix that direction, and how do we use it to write an equation?', v: fTitle, n: `Welcome. Look at four lines through the same point. One rises, one falls, one is flat and one stands straight up. What separates them is direction, and direction is measured by a number called the slope. In this part we use slope to test parallel and perpendicular lines, to find the angle between lines, and to write the first forms of an equation.` }),
    sl('concept', 'What you will be able to do', { ul: ['Find the **slope** from an angle or from two points', 'Test **parallel**, **perpendicular** and **collinear**', 'Find the **angle** between two lines', 'Use **point-slope** and **slope-intercept** forms', 'Build lines **parallel** or **perpendicular** to a given line'], n: `Here are your goals. You will find the slope of a line from its inclination or from two points on it. You will use slopes to test whether lines are parallel, perpendicular, or whether points lie on one line. You will find the angle between two lines, and you will write equations in point-slope and slope-intercept form.` }),
    sl('concept', 'Slope and inclination', { b: r`The **inclination** $\theta$ of a line is the angle it makes with the positive $x$-axis, measured anticlockwise, $0^\circ \le \theta < 180^\circ$. Its **slope** is $m = \tan\theta$. A vertical line has no slope.`, v: tIncl, m: [r`m = \tan\theta`], n: `The inclination of a line is the angle it makes with the positive x axis, measured anticlockwise. The slope is the tangent of that angle. A flat line has slope zero. At forty-five degrees the slope is one. Beyond ninety degrees the tangent is negative, so a falling line has a negative slope. A vertical line has no slope at all, because the tangent of ninety degrees is not defined.` }),
    sl('concept', 'Slope from two points', { b: r`For $A(x_1, y_1)$ and $B(x_2, y_2)$ with $x_1 \ne x_2$: $m = \dfrac{y_2 - y_1}{x_2 - x_1}$, the rise over the run. The order of the points does not matter.`, v: fSlope, m: [r`m = \dfrac{y_2 - y_1}{x_2 - x_1}`], n: `To find the slope from two points, subtract the coordinates in the same order and divide the change in y, the rise, by the change in x, the run. In the figure the run is eight and the rise is six, so the slope is three quarters. If you swap the two points, both differences change sign and the answer stays the same.` }),
    sl('example', 'Worked example 1: slope and inclination', { b: r`Find the slope of the line through $P(-6, 1)$ and $Q(3, -5)$ and the angle it makes with the positive $x$-axis.`, ul: [r`**Slope —** $\dfrac{-5 - 1}{3 - (-6)} = -\dfrac{2}{3}$`, r`**Equation —** $2x + 3y + 9 = 0$`, r`**Inclination —** $\tan\theta = -\dfrac{2}{3}$, so $\theta \approx 146.31^\circ$ (obtuse)`], v: fWE1, n: `The rise from the first point to the second is minus six and the run is nine, so the slope is minus two thirds. A negative slope means the line falls from left to right, and the inclination is an obtuse angle. The tangent inverse of two thirds is about thirty-three point six nine degrees, so the inclination is that taken from one hundred eighty, about one hundred forty-six point three one degrees.` }),
    sl('check', 'Quick check: a slope', { b: 'What is the slope of the line joining the points with coordinates minus five, four and three, minus eight?', chk: 'm01', n: `Subtract in the same order and divide rise by run.` }),
    sl('concept', 'Parallel and perpendicular lines', { b: r`Two non-vertical lines with slopes $m_1$, $m_2$ are **parallel** if $m_1 = m_2$ and **perpendicular** if $m_1m_2 = -1$. A vertical line is perpendicular to a horizontal line.`, v: fPP, m: [r`m_1 = m_2 \ \text{(parallel)}`, r`m_1m_2 = -1 \ \text{(perpendicular)}`], n: `Parallel lines have the same slope. Perpendicular lines have slopes whose product is minus one, which means one slope is the negative reciprocal of the other. In the figure, the first two lines both have slope one half and never meet. The third has slope minus two, and one half times minus two is minus one, so it crosses the first line at right angles.` }),
    sl('example', 'Worked example 2: finding k', { b: r`The line through $(k, -2)$ and $(4, 6)$ is compared with the line through $(-3, 1)$ and $(5, 5)$. Find $k$ if the lines are (i) parallel, (ii) perpendicular.`, ul: [r`**Given slope —** $\dfrac{1}{2}$`, r`**(i)** $\dfrac{8}{4 - k} = \dfrac{1}{2}$, so $k = -12$`, r`**(ii)** $\dfrac{8}{4 - k} = -2$, so $k = 8$`], v: we2iT, n: `The given line has slope one half. The other line has slope eight divided by four minus k. For parallel lines, set that equal to one half. Then four minus k is sixteen, and k is minus twelve. For perpendicular lines, set it equal to minus two, the negative reciprocal. Then four minus k is minus four, and k is eight.` }),
    sl('check', 'Quick check: perpendicular lines', { b: 'True or false: the line through the origin and the point seven, minus four is perpendicular to the line through one, three and minus three, minus four.', chk: 'tf1', n: `Find both slopes and multiply them.` }),
    sl('concept', 'Angle between two lines', { b: r`If $\theta$ is the acute angle between lines of slopes $m_1$ and $m_2$, then $\tan\theta = \left|\dfrac{m_1 - m_2}{1 + m_1m_2}\right|$. If $1 + m_1m_2 = 0$ the lines are perpendicular. The obtuse angle is $180^\circ - \theta$.`, v: tAng, m: [r`\tan\theta = \left|\dfrac{m_1 - m_2}{1 + m_1m_2}\right|`], n: `The tangent of the acute angle between two lines is the size of the difference of the slopes, divided by one plus their product. The table tries four pairs of slopes. When the denominator is zero the lines are perpendicular. For the first pair the tangent is one and the angle is forty-five degrees. The other angle between the same two lines is its supplement.` }),
    sl('example', 'Worked example 3: the angle and the meeting point', { b: r`Find the acute angle between $x - 2y + 3 = 0$ and $2x - y - 3 = 0$, and the point where they meet.`, ul: [r`**Slopes —** $\dfrac{1}{2}$ and $2$`, r`**Tangent —** $\dfrac{3/2}{2} = \dfrac{3}{4}$, so $\theta \approx 36.87^\circ$`, r`**Meeting point —** $P(3, 3)$`], v: fWE3, n: `Solve each equation for y to read the slopes: one half and two. The tangent of the acute angle is the size of one half minus two, which is three halves, divided by one plus one, which is two. That gives three quarters, and an angle of about thirty-six point eight seven degrees. Solving the two equations together shows that the lines cross at the point three, three.` }),
    sl('check', 'Quick check: an angle', { b: 'Two lines have slopes one half and one third. The tangent of the acute angle between them is ____.', chk: 'fb3', n: `Use the tangent formula.` }),
    sl('concept', 'Collinear points', { b: r`Three points $A$, $B$, $C$ are **collinear** if the slope of $AB$ equals the slope of $BC$, since the two segments share $B$.`, v: fCol, n: `Three points lie on one straight line when the slope from the first to the second equals the slope from the second to the third. The figure shows three points whose two slopes are both minus one half. Because the second point is common to both segments, equal slopes force all three points onto a single line.` }),
    sl('concept', 'Point-slope form and special lines', { b: r`The line through $(x_1, y_1)$ with slope $m$ is $y - y_1 = m(x - x_1)$. A horizontal line is $y = k$; a vertical line is $x = h$.`, v: fPS, m: [r`y - y_1 = m(x - x_1)`], n: `If you know one point on a line and its slope, the equation is y minus y one equals m times x minus x one. The figure shows the line through the point two, minus three with slope two thirds. Horizontal lines have equations of the form y equals a constant, and vertical lines have equations of the form x equals a constant.` }),
    sl('example', 'Worked example 4: a parallel line', { b: r`Find the line through $(4, 1)$ that is parallel to the line through $(-1, -3)$ and $(2, 5)$.`, ul: [r`**Slope —** $\dfrac{8}{3}$`, r`**Equation —** $y - 1 = \dfrac{8}{3}(x - 4)$`, r`**Simplify —** $8x - 3y - 29 = 0$`], v: we4T, n: `First find the slope of the given line: eight over three. A parallel line has the same slope. Now use the point-slope form through four, one. Multiply both sides by three to clear the fraction, and collect the terms to get eight x minus three y minus twenty-nine equals zero.` }),
    sl('check', 'Quick check: a vertical line', { b: 'The line drawn through the point minus seven, two at right angles to the x-axis has which equation?', chk: 'm13', n: `Think about which coordinate stays fixed.` }),
    sl('concept', 'Slope-intercept form', { b: r`A line with slope $m$ that meets the $y$-axis at $(0, c)$ has equation $y = mx + c$. The number $c$ is the **$y$-intercept**.`, v: fSI, m: [r`y = mx + c`], n: `When the line meets the y axis at the point zero, c, the equation takes the neat form y equals m x plus c. The figure shows slope three quarters and y intercept minus two. Starting at the intercept, every four units to the right the line rises three units, which gives the other marked points.` }),
    sl('example', 'Worked example 5: a perpendicular line', { b: r`Find the line through $(3, -1)$ perpendicular to $2x + 5y - 4 = 0$.`, ul: [r`**Given slope —** $-\dfrac{2}{5}$`, r`**Perpendicular slope —** $\dfrac{5}{2}$`, r`**Equation —** $5x - 2y - 17 = 0$`], v: we5T, n: `Rewrite the given line as y equals minus two fifths x plus four fifths, so its slope is minus two fifths. The perpendicular slope is the negative reciprocal, five halves. Use point-slope form through three, minus one, clear the fraction, and the equation is five x minus two y minus seventeen equals zero.` }),
    sl('check', 'Quick check: collinear points', { b: 'True or false: the points minus two, minus seven; one, minus one; and four, five all lie on one straight line.', chk: 'tf2', n: `Compare the slopes of the two segments.` }),
    sl('summary', 'Summary', { ul: [r`Slope $m = \tan\theta = \dfrac{y_2 - y_1}{x_2 - x_1}$; a vertical line has no slope`, r`Parallel: $m_1 = m_2$. Perpendicular: $m_1m_2 = -1$`, r`$\tan\theta = \left|\dfrac{m_1 - m_2}{1 + m_1m_2}\right|$ for the acute angle`, r`Collinear points have equal slopes between them`, r`$y - y_1 = m(x - x_1)$ and $y = mx + c$`], v: summary1, n: `To sum up. The slope is the tangent of the inclination, found by rise over run. Parallel lines have equal slopes and perpendicular lines have slopes with product minus one. The tangent formula gives the acute angle between two lines. Collinear points have equal slopes between them. And the point-slope and slope-intercept forms give the equation of a line.` }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: ['**Slope or parallel test (1–2 marks):** show the subtraction and the value', '**Angle between lines (2–3 marks):** slopes, the formula, then the angle', '**Equation of a line (2–3 marks):** the form, the substitution, the simplified result', '**Mistake:** dividing the $x$-difference by the $y$-difference', '**Mistake:** forgetting the modulus in the angle formula', '**Mistake:** using the negative of the slope instead of the negative reciprocal'], n: `In questions on slope, marks go for the formula, the substitution and the final value. For the angle between lines, write both slopes first. Three common slips: dividing run by rise, leaving out the absolute value in the tangent formula, and using the negative of the slope rather than the negative reciprocal for a perpendicular.` }),
  ],
});

// ================================================================ deck 2
const d2k = deck({
  part: 2,
  title: 'Straight Lines — Part 2: More forms, distances and the normal form',
  goals: ['Write the two-point and intercept forms of an equation', 'Convert the general equation to other forms and read slope and intercepts', 'Find the distance of a point from a line', 'Find the distance between parallel lines', 'Reduce a line to normal form (formative only)'],
  slides: [
    sl('title', 'Straight lines, Part 2: Forms and distances', { b: 'A pipe must run from a well to a straight canal by the shortest route. How do we find that distance from the equation of the canal?', v: fDist, n: `Welcome to part two. Here a point sits away from a line, and a perpendicular joins them. That perpendicular is the shortest route, and its length is the distance from the point to the line. We will first finish the forms of an equation, then find this distance, the distance between parallel lines, and meet the normal form.` }),
    sl('concept', 'What you will be able to do', { ul: ['Use the **two-point** and **intercept** forms', 'Read slope and intercepts from the **general equation**', 'Find the **distance of a point** from a line', 'Find the **distance between parallel lines**', 'Meet the **normal form** (formative only)'], n: `Here are your goals. You will write the equation of a line through two points and from its intercepts. You will convert the general equation to other forms. You will find the distance of a point from a line and between two parallel lines. Finally you will meet the normal form, which is for practice and is not examined in the board paper.` }),
    sl('concept', 'Two-point form', { b: r`The line through $(x_1, y_1)$ and $(x_2, y_2)$ is $y - y_1 = \dfrac{y_2 - y_1}{x_2 - x_1}(x - x_1)$. It is the point-slope form with the slope found from the two points.`, v: fTwo, m: [r`y - y_1 = \dfrac{y_2 - y_1}{x_2 - x_1}(x - x_1)`], n: `Given two points, first find the slope, then use the point-slope form with either point. The result is called the two-point form. The figure shows the line through minus three, minus four and six, two. It does not matter which point you use, and it is wise to check the other point in your answer.` }),
    sl('example', 'Worked example 1: two points', { b: r`Find the equation of the line through $A(-3, -4)$ and $B(6, 2)$.`, ul: [r`**Slope —** $\dfrac{6}{9} = \dfrac{2}{3}$`, r`**Form —** $y + 4 = \dfrac{2}{3}(x + 3)$`, r`**Result —** $2x - 3y - 6 = 0$`], v: we1T, n: `The slope is six over nine, which is two thirds. Use the point minus three, minus four: y plus four equals two thirds of x plus three. Multiply by three and rearrange to get two x minus three y minus six equals zero. Check with the other point: two times six minus three times two minus six is zero, as it should be.` }),
    sl('check', 'Quick check: the y-intercept', { b: 'The line through two, one and six, nine cuts the y axis at the point zero, ____.', chk: 'fb2', n: `Find the equation first, then put x equal to zero.` }),
    sl('concept', 'Intercept form', { b: r`A line with $x$-intercept $a$ and $y$-intercept $b$ (both nonzero) is $\dfrac{x}{a} + \dfrac{y}{b} = 1$. Intercepts are signed: they can be negative.`, v: fInt, m: [r`\dfrac{x}{a} + \dfrac{y}{b} = 1`], n: `If a line cuts the x axis at a and the y axis at b, its equation is x over a plus y over b equals one. In the figure a is five and b is minus three. Intercepts are signed lengths, so a line that cuts below the origin has a negative y intercept. A line through the origin has no intercept form.` }),
    sl('example', 'Worked example 2: from the intercepts', { b: r`Find the line with intercepts $5$ on the $x$-axis and $-3$ on the $y$-axis.`, ul: [r`**Form —** $\dfrac{x}{5} + \dfrac{y}{-3} = 1$`, r`**Multiply by 15 —** $3x - 5y = 15$`, r`**Result —** $3x - 5y - 15 = 0$`], v: we2iT, n: `Put a equal to five and b equal to minus three. The equation is x over five plus y over minus three equals one. Multiply every term by fifteen to clear the fractions, giving three x minus five y equals fifteen. As a check, the point minus five, minus six also satisfies the equation.` }),
    sl('check', 'Quick check: from intercepts', { b: 'A straight line makes an intercept of minus four on the x axis and six on the y axis. Which equation is it?', chk: 'm11', n: `Write the intercept form, then clear the fractions.` }),
    sl('concept', 'The general equation (formative)', { b: r`Every straight line has an equation $Ax + By + C = 0$ with $A$, $B$ not both zero. This slide is formative only: the slope is $-\dfrac{A}{B}$ and the intercepts are $-\dfrac{C}{A}$ and $-\dfrac{C}{B}$.`, v: genT, n: `Every straight line can be written as A x plus B y plus C equals zero. This idea is for practice and is not examined in the board paper, but it is useful. The slope is minus A over B. The intercepts are minus C over A on the x axis and minus C over B on the y axis. If B is zero the line is vertical, and if C is zero it passes through the origin.` }),
    sl('example', 'Worked example 3: changing the form', { b: r`Reduce $3x - 4y + 24 = 0$ to slope-intercept and intercept forms.`, ul: [r`**Slope-intercept —** $y = \dfrac{3}{4}x + 6$`, r`**Intercept form —** $\dfrac{x}{-8} + \dfrac{y}{6} = 1$`], v: we3T2, n: `To get the slope-intercept form, solve for y: four y equals three x plus twenty-four, so y equals three quarters x plus six. To get the intercept form, move the constant to the right side to get three x minus four y equals minus twenty-four, and divide by minus twenty-four. The intercepts are minus eight and six.` }),
    sl('concept', 'Distance of a point from a line', { b: r`The distance of $(x_0, y_0)$ from $ax + by + c = 0$ is $d = \dfrac{|ax_0 + by_0 + c|}{\sqrt{a^2 + b^2}}$, measured along the perpendicular.`, v: fDist, m: [r`d = \dfrac{|ax_0 + by_0 + c|}{\sqrt{a^2 + b^2}}`], n: `The distance from a point to a line is the length of the perpendicular. Substitute the point into the left side of the equation, take the absolute value, and divide by the square root of a squared plus b squared. In the figure the point four, five and the line three x plus four y minus twelve give twenty over five, which is four.` }),
    sl('example', 'Worked example 4: a distance', { b: r`Find the distance of $(6, 5)$ from $3x + 4y - 9 = 0$.`, ul: [r`**Substitute —** $3(6) + 4(5) - 9 = 29$`, r`**Root —** $\sqrt{9 + 16} = 5$`, r`**Distance —** $\dfrac{29}{5} = 5.8$ units`], v: we4T2, n: `Put six and five into the expression three x plus four y minus nine. It gives twenty-nine. The root of nine plus sixteen is five. So the distance is twenty-nine over five, which is five point eight units. Always take the absolute value, because a distance cannot be negative.` }),
    sl('check', 'Quick check: a distance', { b: 'The distance of the point minus five, seven from the line five x plus twelve y minus twenty equals zero is which value?', chk: 'm15', n: `Substitute the point and divide by thirteen.` }),
    sl('example', 'Worked example 5: a distance in surd form', { b: r`Find the distance of $(3, 7)$ from $2x - 3y + 4 = 0$.`, ul: [r`**Substitute —** $2(3) - 3(7) + 4 = -11$`, r`**Root —** $\sqrt{4 + 9} = \sqrt{13}$`, r`**Distance —** $\dfrac{11}{\sqrt{13}} = \dfrac{11\sqrt{13}}{13}$`], v: we5T2, n: `Substituting the point gives minus eleven. The root of four plus nine is root thirteen. The distance is eleven over root thirteen. To rationalise, multiply the top and bottom by root thirteen, giving eleven root thirteen over thirteen, which is about three point zero five units.` }),
    sl('concept', 'Distance between parallel lines', { b: r`For parallel lines $ax + by + c_1 = 0$ and $ax + by + c_2 = 0$ with the same $a$ and $b$: $d = \dfrac{|c_1 - c_2|}{\sqrt{a^2 + b^2}}$.`, v: fPar, m: [r`d = \dfrac{|c_1 - c_2|}{\sqrt{a^2 + b^2}}`], n: `Parallel lines stay the same distance apart. First make the coefficients of x and y equal in both equations. Then the distance is the difference of the constants, in absolute value, divided by the square root of a squared plus b squared. In the figure the constants are minus twelve and eight, so the distance is twenty over five, which is four.` }),
    sl('example', 'Worked example 6: unequal coefficients', { b: r`Find the distance between $6x - 8y + 15 = 0$ and $3x - 4y - 5 = 0$.`, ul: [r`**Match —** $3x - 4y - 5 = 0$ becomes $6x - 8y - 10 = 0$`, r`**Distance —** $\dfrac{|15 - (-10)|}{10} = 2.5$ units`], v: we6T, n: `The coefficients are different, so first double the second equation to get six x minus eight y minus ten equals zero. Now the constants are fifteen and minus ten, which differ by twenty-five. The root of thirty-six plus sixty-four is ten. So the distance is twenty-five over ten, or two point five units.` }),
    sl('check', 'Quick check: not yet matched', { b: 'True or false: the parallel lines eight x plus six y minus fifteen and four x plus three y plus five are exactly two units apart.', chk: 'tf4', n: `Make the coefficients equal before using the formula.` }),
    sl('concept', 'Normal form (formative)', { b: r`The line at perpendicular distance $p > 0$ from the origin, whose perpendicular makes angle $\omega$ with the positive $x$-axis, is $x\cos\omega + y\sin\omega = p$. This slide is formative only.`, v: fNorm, m: [r`x\cos\omega + y\sin\omega = p`], n: `This idea is for practice and is not examined in the board paper. Draw the perpendicular from the origin to the line. Its length is p, and its direction makes an angle omega with the x axis. Then the equation is x cosine omega plus y sine omega equals p. In the figure, p is four, the cosine is three fifths and the sine is four fifths.` }),
    sl('example', 'Worked example 7: reduce to normal form', { b: r`Reduce $x + y - 6 = 0$ to normal form.`, ul: [r`**Divide by $\sqrt{2}$ —** $\dfrac{1}{\sqrt{2}}x + \dfrac{1}{\sqrt{2}}y = 3\sqrt{2}$`, r`**Read off —** $\omega = 45^\circ$, $p = 3\sqrt{2}$`], v: we7T, n: `Write the equation as x plus y equals six. The square root of one plus one is root two, so divide every term by root two. The cosine and the sine are both root two over two, which means the angle is forty-five degrees. The distance p is six over root two, which is three root two, a positive number as required.` }),
    sl('summary', 'Summary', { ul: [r`Two-point form: slope from the points, then $y - y_1 = m(x - x_1)$`, r`Intercept form: $\dfrac{x}{a} + \dfrac{y}{b} = 1$`, r`General form $Ax + By + C = 0$: slope $-\dfrac{A}{B}$ (formative)`, r`$d = \dfrac{|ax_0 + by_0 + c|}{\sqrt{a^2 + b^2}}$; parallel lines: $\dfrac{|c_1 - c_2|}{\sqrt{a^2 + b^2}}$`, r`Normal form $x\cos\omega + y\sin\omega = p$, $p > 0$ (formative)`], v: summary2, n: `To sum up. The two-point form uses the slope between two points. The intercept form uses the two intercepts. The distance of a point from a line is the absolute value of the expression divided by the root of a squared plus b squared. For parallel lines, match the coefficients and use the difference of the constants. The normal form is a formative extra.` }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: ['**Equation of a line (2–3 marks):** the form, the substitution, the simplified equation', '**Distance (2–3 marks):** the expression value, the root, the final distance', '**Parallel lines (2–3 marks):** match the coefficients first', '**Mistake:** forgetting the modulus in the distance formula', '**Mistake:** using unequal coefficients in the parallel-distance formula', '**Mistake:** mixing up the $x$- and $y$-intercepts in the intercept form'], n: `In questions on distance, marks go for the substitution, the root and the final value. For parallel lines, show how you matched the coefficients. Three common slips: leaving out the absolute value, using the parallel formula when the coefficients do not match, and swapping the x and y intercepts in the intercept form.` }),
  ],
});

// ================================================================ notes
const notes = {
  unit: 'cbse-11-mathematics-ch09', version: 1, title: 'Straight Lines — chapter notes', language: 'en',
  sections: [
    { heading: '1. Slope and inclination', body_md: r`The **inclination** $\theta$ of a line is the angle it makes with the positive $x$-axis, $0^\circ \le \theta < 180^\circ$. The **slope** is $m = \tan\theta$; a vertical line has none.\n\nFrom two points, $m = \dfrac{y_2 - y_1}{x_2 - x_1}$ with $x_1 \ne x_2$. Positive slope: rising; negative: falling; zero: horizontal.\n\nFrom $ax + by + c = 0$: $m = -\dfrac{a}{b}$ for $b \ne 0$.`, key_terms: [{ term: 'Inclination', definition_md: r`The angle $\theta$ a line makes with the positive $x$-axis.` }, { term: 'Slope', definition_md: r`$m = \tan\theta$, the rise over the run.` }], formulas: [{ latex: r`m = \tan\theta = \dfrac{y_2 - y_1}{x_2 - x_1}`, label: 'Slope' }], visual: tIncl, visuals: [fSlope, fWE1], topic_ids: [topic(1)] },
    { heading: '2. Parallel, perpendicular and collinear', body_md: r`Non-vertical lines: parallel if $m_1 = m_2$; perpendicular if $m_1m_2 = -1$. A vertical and a horizontal line are perpendicular.\n\nThree points $A$, $B$, $C$ are collinear if the slope of $AB$ equals the slope of $BC$.\n\nFor a line $ax + by + c = 0$, a parallel line keeps $a$ and $b$ and changes $c$; a perpendicular has the form $bx - ay + k = 0$.`, key_terms: [{ term: 'Collinear', definition_md: 'Lying on one straight line.' }], formulas: [{ latex: r`m_1 = m_2 \quad\text{or}\quad m_1m_2 = -1`, label: 'Parallel or perpendicular' }], visual: ppTable, visuals: [fPP, fCol, we2iT], topic_ids: [topic(1)] },
    { heading: '3. Angle between two lines', body_md: r`If $\theta$ is the acute angle between lines with slopes $m_1$, $m_2$: $\tan\theta = \left|\dfrac{m_1 - m_2}{1 + m_1m_2}\right|$. The obtuse angle is $180^\circ - \theta$.\n\nIf $1 + m_1m_2 = 0$ the lines are perpendicular. If one line is vertical, $\tan\theta = \left|\dfrac{1}{m}\right|$ for the other. For equations in general form the same angle has $\tan\theta = \dfrac{|a_1b_2 - a_2b_1|}{|a_1a_2 + b_1b_2|}$.`, key_terms: [{ term: 'Acute angle between lines', definition_md: 'The smaller of the two angles two intersecting lines make; the other is its supplement.' }], formulas: [{ latex: r`\tan\theta = \left|\dfrac{m_1 - m_2}{1 + m_1m_2}\right|`, label: 'Angle between lines' }], visual: tAng, visuals: [fWE3, we3T], topic_ids: [topic(1)] },
    { heading: '4. Point-slope and slope-intercept forms', body_md: r`Horizontal line: $y = k$. Vertical line: $x = h$.\n\nPoint-slope: $y - y_1 = m(x - x_1)$. Slope-intercept: $y = mx + c$, where $c$ is the $y$-intercept.\n\nA line parallel to a given one through a point keeps the slope; a perpendicular uses the negative reciprocal.`, key_terms: [{ term: 'y-intercept', definition_md: r`The value $c$ where the line meets the $y$-axis, at $(0, c)$.` }], formulas: [{ latex: r`y - y_1 = m(x - x_1)`, label: 'Point-slope' }, { latex: r`y = mx + c`, label: 'Slope-intercept' }], visual: hvT, visuals: [fPS, fSI, we4T, we5T], topic_ids: [topic(2)] },
    { heading: '5. Two-point and intercept forms', body_md: r`Two-point: $y - y_1 = \dfrac{y_2 - y_1}{x_2 - x_1}(x - x_1)$.\n\nIntercept form: $\dfrac{x}{a} + \dfrac{y}{b} = 1$ for a line with $x$-intercept $a$ and $y$-intercept $b$, both nonzero. A line through the origin, or parallel to an axis, has no intercept form.\n\nAlways check a second point in the final equation.`, key_terms: [{ term: 'x-intercept', definition_md: r`The value $a$ where the line meets the $x$-axis, at $(a, 0)$.` }], formulas: [{ latex: r`\dfrac{x}{a} + \dfrac{y}{b} = 1`, label: 'Intercept form' }], visual: fTwo, visuals: [we1T, fInt, we2iT], topic_ids: [topic(2)] },
    { heading: '6. Distance of a point from a line', body_md: r`The perpendicular distance of $(x_0, y_0)$ from $ax + by + c = 0$ is $d = \dfrac{|ax_0 + by_0 + c|}{\sqrt{a^2 + b^2}}$. The distance of the origin is $\dfrac{|c|}{\sqrt{a^2 + b^2}}$.\n\nLeave surd answers in rationalised form, for example $\dfrac{11\sqrt{13}}{13}$. The altitude of a triangle from a vertex is the distance of the vertex from the opposite side.`, key_terms: [{ term: 'Perpendicular distance', definition_md: 'The shortest distance from a point to a line, measured along the perpendicular.' }], formulas: [{ latex: r`d = \dfrac{|ax_0 + by_0 + c|}{\sqrt{a^2 + b^2}}`, label: 'Point to line' }], visual: fDist, visuals: [we4T2, we5T2], topic_ids: [topic(3)] },
    { heading: '7. Distance between parallel lines', body_md: r`For $ax + by + c_1 = 0$ and $ax + by + c_2 = 0$: $d = \dfrac{|c_1 - c_2|}{\sqrt{a^2 + b^2}}$. The coefficients of $x$ and $y$ must be equal first.\n\nA line half-way between two parallels has the mean of their constants.`, key_terms: [{ term: 'Parallel lines', definition_md: 'Lines with equal slopes that never meet, a constant distance apart.' }], formulas: [{ latex: r`d = \dfrac{|c_1 - c_2|}{\sqrt{a^2 + b^2}}`, label: 'Between parallels' }], visual: fPar, visuals: [we6T], topic_ids: [topic(3)] },
    { heading: '8. General equation and normal form (formative only)', body_md: r`This section is for practice and is not examined in the board paper.\n\nGeneral equation $Ax + By + C = 0$: slope $-\dfrac{A}{B}$, intercepts $-\dfrac{C}{A}$ and $-\dfrac{C}{B}$.\n\nNormal form $x\cos\omega + y\sin\omega = p$ with $p > 0$: divide by $\sqrt{A^2 + B^2}$ and change signs so that $p$ is positive.`, key_terms: [{ term: 'Normal form', definition_md: r`$x\cos\omega + y\sin\omega = p$, where $p > 0$ is the distance of the line from the origin.` }], formulas: [{ latex: r`x\cos\omega + y\sin\omega = p`, label: 'Normal form' }], visual: genT, visuals: [we3T2, fNorm, we7T], topic_ids: [topic(4)] },
  ],
  exam_tips_md: r`**How marks are awarded**\n- *Slope, parallel or perpendicular test (1–2 marks):* the formula, the substitution and the value.\n- *Angle between lines (2–3 marks):* both slopes, the tangent formula, the angle; mention the obtuse angle if asked.\n- *Equation of a line (2–3 marks):* name the form, substitute, simplify to $ax + by + c = 0$, and check a point.\n- *Distance (2–3 marks):* substitute into the modulus formula, evaluate the root, state the units.\n- *Parallel lines and triangles (3–5 marks):* match the coefficients, or find the altitude as a distance, then the area.\n\n**Common mistakes**\n1. Dividing run by rise.\n2. Dropping the modulus in the angle or distance formula.\n3. Using the negative of the slope instead of the negative reciprocal.\n4. Using the parallel-distance formula with unequal coefficients.\n5. Swapping the $x$- and $y$-intercepts in the intercept form.\n6. Forgetting that a vertical line has no slope.\n7. Leaving a surd distance with an irrational denominator.`,
  status: 'draft', provenance: d1.provenance,
};

